<?php
declare(strict_types=1);
if(!in_array($path,['/releases','/installations','/update-events','/revocations'],true))return;
login_required();
if($path==='/revocations'&&$_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$licenseId=(int)($_POST['license_id']??0);$reason=mb_substr(trim((string)($_POST['reason']??'')),0,500);if($licenseId<1||$reason==='')throw new RuntimeException('Licence and reason are required.');q('INSERT INTO license_revocations(license_id,reason,effective_at) VALUES(?,?,CURRENT_TIMESTAMP)',[$licenseId,$reason]);q("UPDATE licenses SET status='revoked' WHERE id=?",[$licenseId]);q('INSERT INTO events(license_id,action,detail) VALUES(?,?,?)',[$licenseId,'licence.revoked',$reason]);header('Location: ./revocations');exit;}
if($path==='/revocations'&&$_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['restore'])){require_csrf();$licenseId=(int)$_POST['restore'];q('UPDATE license_revocations SET expires_at=CURRENT_TIMESTAMP WHERE license_id=? AND expires_at IS NULL',[$licenseId]);q("UPDATE licenses SET status='active' WHERE id=?",[$licenseId]);q('INSERT INTO events(license_id,action,detail) VALUES(?,?,?)',[$licenseId,'licence.restored','Admin review']);header('Location: ./revocations');exit;}
if($path==='/revocations'){$rows='';foreach(q('SELECT r.*,l.key_hint,l.product FROM license_revocations r JOIN licenses l ON l.id=r.license_id ORDER BY r.created_at DESC')->fetchAll() as $r)$rows.='<tr><td>'.(int)$r['license_id'].' · '.esc($r['key_hint']).'</td><td>'.esc($r['product']).'</td><td>'.esc($r['reason']).'</td><td>'.esc($r['effective_at']??'').'</td><td>'.esc($r['expires_at']??'active').'</td><td><form method="post"><input type="hidden" name="csrf" value="'.csrf().'"/><input type="hidden" name="restore" value="'.(int)$r['license_id'].'"/><button>Restore after review</button></form></td></tr>';layout('Licence review','<div class="card"><h2>Licence revocations</h2><p>Use only for verified support, contractual or legal review. Restore requires an explicit admin action.</p><form method="post"><input type="hidden" name="csrf" value="'.csrf().'"> <input type="number" name="license_id" placeholder="Licence ID" required><input name="reason" placeholder="Reason" required><button>Revoke licence</button></form></div><div class="card"><table><tr><th>Licence</th><th>Product</th><th>Reason</th><th>Effective</th><th>Expires</th><th>Action</th></tr>'.$rows.'</table></div>');exit;}
if($path==='/releases'){$rows='';foreach(q("SELECT r.*,p.slug FROM application_releases r JOIN products p ON p.id=r.product_id ORDER BY r.created_at DESC")->fetchAll() as $r)$rows.='<tr><td>'.esc($r['slug']).'</td><td>'.esc($r['version']).'</td><td>'.esc($r['channel']).'</td><td>'.esc($r['status']).'</td><td>'.esc($r['min_php']).'</td><td>'.(int)$r['migration_version'].'</td><td>'.esc($r['sha256']).'</td><td>'.esc($r['created_at']).'</td></tr>';layout('Application releases','<div class="card"><h2>Application releases</h2><p>Published packages are served only after licence and domain validation.</p><table><tr><th>Product</th><th>Version</th><th>Channel</th><th>Status</th><th>PHP</th><th>Migration</th><th>SHA-256</th><th>Created</th></tr>'.$rows.'</table></div>');exit;}
if($path==='/installations'){$rows='';foreach(q('SELECT i.*,l.key_hint FROM installations i LEFT JOIN licenses l ON l.id=i.license_id ORDER BY i.last_seen_at DESC')->fetchAll() as $i)$rows.='<tr><td>'.esc($i['product']).'</td><td>'.esc($i['domain']).'</td><td>'.esc($i['installed_version']).'</td><td>'.esc($i['php_version']).'</td><td>'.esc($i['status']).'</td><td>'.esc($i['last_seen_at']).'</td><td>'.esc($i['key_hint']??'').'</td></tr>';layout('Installations','<div class="card"><h2>Authorised installations</h2><p>Only installation identifiers, domain and technical version signals are retained.</p><table><tr><th>Product</th><th>Domain</th><th>Version</th><th>PHP</th><th>Status</th><th>Last seen</th><th>Licence</th></tr>'.$rows.'</table></div>');exit;}
$rows='';foreach(q('SELECT e.*,i.domain FROM update_events e LEFT JOIN installations i ON i.id=e.installation_id ORDER BY e.created_at DESC LIMIT 300')->fetchAll() as $e)$rows.='<tr><td>'.esc($e['created_at']).'</td><td>'.esc($e['domain']??'').'</td><td>'.esc($e['action']).'</td><td>'.esc($e['from_version']).' → '.esc($e['to_version']).'</td><td>'.esc($e['detail']).'</td></tr>';layout('Update events','<div class="card"><h2>Update event log</h2><p>Use this audit trail for support and lawful licence review; it is not a server scanner.</p><table><tr><th>Time</th><th>Domain</th><th>Action</th><th>Versions</th><th>Detail</th></tr>'.$rows.'</table></div>');exit;
